function nxShippingBody(config){var shipping=config.shipping||{},fields=shipping.fields||[],used=fields.map(function(row){return row.id;}),mode=shipping.pricing_mode||"quote",fee=Number(shipping.flat_fee_cop||0),pricingRows=[["flat","Tarifa fija","El bot la suma al producto antes de cobrar."],["free","Envío gratis","El total será igual al subtotal de productos."],["quote","Por confirmar","El bot no cobra hasta que tu equipo cotice."]],priceFields=mode==="flat"?'<div class="nxFieldGrid">'+nxField("Costo estándar del envío (COP)","shipping.flat_fee_cop",shipping.flat_fee_cop||"","number")+nxField("Envío gratis desde (COP, opcional)","shipping.free_over_cop",shipping.free_over_cop||"","number")+'</div>':"",shippingPreview=mode==="flat"?(fee>0?("El envío cuesta $"+fee.toLocaleString("es-CO")+" COP y lo sumo al total antes del pago."):"Escribe la tarifa para que pueda calcular el total antes de cobrar."):(mode==="free"?"El envío es gratis. Solo pagas los productos.":"Primero confirmaré el valor del envío. No te cobraré un total incompleto.");return '<div class="nxConfigBodyGrid"><div class="nxConfigControls">'+nxQuestion("¿Cómo cobras el envío?","Este valor se suma automáticamente al pedido. Si aún no tienes una tarifa, el bot debe esperar una cotización.")+'<div class="nxChoiceGrid one">'+pricingRows.map(function(row){return '<button type="button" class="nxChoice '+(mode===row[0]?"active":"")+'" data-shipping-mode="'+row[0]+'" onclick="nxSetShippingMode(this)"><span><strong>'+row[1]+'</strong><br>'+row[2]+'</span></button>';}).join("")+'</div>'+priceFields+nxField("Cobertura, tiempos y excepciones","shipping.policy",shipping.policy||"","textarea")+nxQuestion("Cuando tu cliente pide un envío, ¿qué le pregunta el bot?","Los pide de a uno, en este orden, y no avanza hasta tener los obligatorios.")+'<div class="nxEditableList">'+fields.map(function(field,index){return '<div class="nxEditableRow"><span>'+String(index+1).padStart(2,"0")+'</span><input value="'+attr(field.label)+'" data-ship-label="'+index+'"><button class="nxRequired '+(field.required?"":"optional")+'" type="button" data-ship-required="'+index+'" onclick="nxToggleShippingRequired(this)">'+(field.required?"Obligatorio":"Opcional")+'</button><button class="nxRemove" type="button" data-ship-remove="'+index+'" onclick="nxRemoveShipping(this)" aria-label="Quitar campo">×</button></div>';}).join("")+'</div><div class="nxSuggestionBox"><strong>✦ Otros negocios también piden</strong>'+nxChips(NX_SHIPPING_SUGGESTIONS.filter(function(row){return used.indexOf(row[0])<0;}),[],"shippingAdd")+'</div></div>'+nxPreview("¿Cuánto cuesta el envío?",shippingPreview)+'</div>';}
