function nxAppointmentRequirementsBody(){if(state.nxAppointmentRequirementsLoading)return '<div class="nxApptRequirements"><p class="nxConfigHelp">Cargando la configuración de citas…</p></div>';var rows=state.nxAppointmentRequirements||nxDefaultAppointmentRequirements(),canEdit=state.nxAppointmentRequirementsCanEdit===true;return '<div class="nxApptRequirements" data-form-type="other">'+nxQuestion("¿Qué debe pedir antes de confirmar una cita?","Activa los datos que necesita tu negocio y decide cuáles son obligatorios u opcionales.")+'<div class="nxApptRequirementList">'+rows.map(function(item){var custom=item.type==="custom",copy=custom?'<input type="text" name="nx_appt_custom_question_'+attr(item.id)+'" maxlength="160" value="'+attr(item.question)+'" placeholder="Escribe tu pregunta" autocomplete="off" autocorrect="off" autocapitalize="sentences" spellcheck="false" data-1p-ignore="true" data-lpignore="true" data-bwignore="true" data-protonpass-ignore="true" data-form-type="other" data-nx-appt-question="'+attr(item.id)+'" aria-label="Pregunta personalizada">':'<strong>'+esc(item.label)+'</strong><small>'+esc(item.question)+'</small>';return '<div class="nxApptRequirementRow"><button class="nxApptRequirementToggle '+(item.active?'on':'')+'" type="button" data-nx-appt-toggle="'+attr(item.id)+'" onclick="nxToggleAppointmentRequirement(this.dataset.nxApptToggle)" aria-pressed="'+(item.active?'true':'false')+'" '+(canEdit?'':'disabled')+'></button><span class="nxApptRequirementCopy">'+copy+'</span><select class="nxApptRequirementMode" data-nx-appt-mode="'+attr(item.id)+'" onchange="nxSetAppointmentRequirementMode(this.dataset.nxApptMode,this.value)" '+(canEdit&&item.active?'':'disabled')+' autocomplete="off" data-form-type="other"><option value="required" '+(item.required?'selected':'')+'>Obligatorio</option><option value="optional" '+(!item.required?'selected':'')+'>Opcional</option></select>'+(custom?'<button class="nxRemove" type="button" data-nx-appt-remove="'+attr(item.id)+'" onclick="nxRemoveAppointmentRequirement(this.dataset.nxApptRemove)" aria-label="Eliminar pregunta" '+(canEdit?'':'disabled')+'>×</button>':'<span></span>')+'</div>';}).join("")+'</div><div class="nxApptRequirementComposer"><label class="nxConfigField"><span>Pregunta personalizada</span><input id="nxNewAppointmentRequirement" type="text" name="nx_new_appointment_requirement_question" maxlength="160" placeholder="Ej. ¿Hay algo que debamos tener en cuenta?" autocomplete="off" autocorrect="off" autocapitalize="sentences" spellcheck="false" data-1p-ignore="true" data-lpignore="true" data-bwignore="true" data-protonpass-ignore="true" data-form-type="other" '+(canEdit?'':'disabled')+'></label><select id="nxNewAppointmentRequirementMode" '+(canEdit?'':'disabled')+' autocomplete="off" data-form-type="other"><option value="required">Obligatorio</option><option value="optional">Opcional</option></select><button class="nxAddDashed" type="button" onclick="nxAddAppointmentRequirement()" '+(canEdit?'':'disabled')+'>+ Añadir otra pregunta</button></div><div class="nxApptRequirementFooter"><span class="nxApptRequirementState '+attr(state.nxAppointmentRequirementsStatus||'')+'" id="nxAppointmentRequirementsStatus">'+esc(state.nxAppointmentRequirementsMessage||(canEdit?'Configuración lista para editar.':'Solo lectura'))+'</span><button class="ghostBtn" type="button" onclick="nxSaveAppointmentRequirements(true)" '+(canEdit?'':'disabled')+'>Guardar y aplicar al bot</button></div></div>';}
function nxLogoDrag(event,active){if(event){event.preventDefault();event.stopPropagation();}var drop=document.getElementById("nxProfileImageDrop");if(drop)drop.classList.toggle("drag",!!active);}
function nxDropLogo(event){nxLogoDrag(event,false);if(!state.personalityCanEdit)return;var file=event&&event.dataTransfer&&event.dataTransfer.files&&event.dataTransfer.files[0];nxSelectLogoFile(file);}
function nxSelectLogoFile(file){if(!file||!state.personalityCanEdit)return;preparePanelImage(file).then(function(image){state.personality.profile.avatar_url=image;nxConfigurationChanged(true);nxToast("Imagen cargada y guardándose.");}).catch(function(error){nxToast(error&&error.message||"No pudimos procesar esa imagen.");});}
function nxRemoveLogo(event){if(event){event.preventDefault();event.stopPropagation();}if(!state.personalityCanEdit)return;state.personality.profile.avatar_url="";nxConfigurationChanged(true);}
function nxToggleSwitch(button){var path=button.getAttribute("data-nx-switch"),next=!nxGet(state.personality,path);nxSet(state.personality,path,next);nxConfigurationChanged(true);}
function nxToggleChip(button){var group=button.getAttribute("data-nx-group"),value=button.getAttribute("data-nx-chip");if(group==="greetingTone"||group==="farewellTone"){var kind=group==="greetingTone"?"greeting":"farewell",proposals=kind==="greeting"?NX_GREETING_PROPOSALS:NX_FAREWELL_PROPOSALS;state.personality[kind].tone=value;state.personality[kind].selected=0;state.personality[kind].custom=false;state.personality[kind].text=proposals[value][0].replace(/\\{negocio\\}/g,nxBusinessName());nxConfigurationChanged(true);return;}if(group==="shippingAdd"){state.personality.shipping.fields.push({id:value,label:button.textContent.trim(),required:false});nxConfigurationChanged(true);return;}var path={reminderType:"reminders.type",reminderTimings:"reminders.timings",paymentMethods:"payments.methods",escalationTriggers:"escalation.triggers"}[group];if(!path)return;if(group==="reminderType"){nxSet(state.personality,path,value);nxConfigurationChanged(true);return;}var list=nxGet(state.personality,path)||[],index=list.indexOf(value);if(index>=0)list.splice(index,1);else list.push(value);nxSet(state.personality,path,list);nxConfigurationChanged(true);}
function nxSelectProposal(button){var kind=button.getAttribute("data-kind"),index=Number(button.getAttribute("data-choice"))||0,proposals=kind==="greeting"?NX_GREETING_PROPOSALS:NX_FAREWELL_PROPOSALS,tone=state.personality[kind].tone||"cercano";state.personality[kind].selected=index;state.personality[kind].custom=false;state.personality[kind].text=proposals[tone][index].replace(/\\{negocio\\}/g,nxBusinessName());nxConfigurationChanged(true);}
