function nxAddFaq(){state.personality.faqs.push({id:"faq-"+Date.now(),question:"",answer:""});nxConfigurationChanged(true);}
function nxRemoveFaq(button){state.personality.faqs.splice(Number(button.getAttribute("data-faq-remove")),1);nxConfigurationChanged(true);}
function nxSetSaveState(mode,label){var node=document.getElementById("nxConfigSaveState");if(!node)return;node.className="nxSaveState "+mode;node.textContent=label;}
function nxSetApplyButton(busy){var button=document.getElementById("nxApplyConfigBtn");if(!button)return;button.disabled=!!busy||!state.personalityCanEdit;button.textContent=busy?"Aplicando…":"Guardar y aplicar cambios";}
function nxToast(message,mode){var node=document.getElementById("nxConfigToast");if(!node)return;node.textContent=(mode==="error"?"Error: ":"✓ ")+message;node.hidden=false;clearTimeout(nxConfigToastTimer);nxConfigToastTimer=setTimeout(function(){node.hidden=true;},4200);}
function nxShowWhatsAppProfileSync(sync,notify){if(!sync)return;state.whatsappProfileSync=sync;if(sync.status==="applied"){nxSetSaveState("saved","Bot y WhatsApp actualizados");if(notify)nxToast(sync.message||"El perfil también quedó actualizado en WhatsApp.");return;}if(sync.status==="manual_app_required"){nxSetSaveState("warning","Bot aplicado · actualiza el perfil en WhatsApp Business");if(notify)nxToast(sync.message||"Abre WhatsApp Business en el celular → Configuración → Herramientas para la empresa → Perfil de empresa.");return;}if(sync.status==="pending_connection"){nxSetSaveState("warning","Bot aplicado · conecta WhatsApp");if(notify)nxToast(sync.message||"Los cambios quedaron guardados; falta conectar WhatsApp.");return;}if(sync.status==="failed"){nxSetSaveState("error","Bot aplicado · WhatsApp no actualizado");if(notify)nxToast(sync.message||"Meta no confirmó el perfil de WhatsApp.","error");}}
function fillBotPersonality(payload){state.personality=nxClone(payload&&payload.personality||{});state.personalityFeatures=payload&&payload.features||{};state.personalityPlan=payload&&payload.plan_id||state.personality.plan_id||"nextfor-uno";state.whatsappProfileSync=payload&&payload.whatsapp_profile_sync||state.whatsappProfileSync||null;if(payload&&typeof payload.can_edit==="boolean")state.personalityCanEdit=payload.can_edit;state.personalityDirty=false;text("nxConfigPlan",String(state.personalityPlan).replace("nextfor-","Nextfor "));var applied=payload&&payload.applied===true;nxSetSaveState(state.personalityCanEdit?(applied?"saved":"error"):"readonly",state.personalityCanEdit?(applied?"Aplicado al bot":"No aplicado al bot"):"Solo lectura");renderBotConfiguration();nxApplyEditPermissions();nxSetApplyButton(false);nxShowWhatsAppProfileSync(payload&&payload.whatsapp_profile_sync,false);if(PANEL_CONTEXT.appointments&&state.personalityFeatures.reminders)nxLoadAppointmentRequirements(false);}
function loadBotPersonality(force){if(state.personalityLoading||(!force&&state.personality&&!state.personalityDirty))return;state.personalityLoading=true;nxSetSaveState("loading","Cargando…");api(PANEL_PERSONALITY_PATH).then(fillBotPersonality).catch(function(error){nxSetSaveState("error",error.status===401?"Sesión vencida":"No se pudo cargar");}).finally(function(){state.personalityLoading=false;});}
function syncBotWhatsAppProfile(){if(nxConfigSaving)return;nxConfigSaving=true;nxSetApplyButton(true);nxSetSaveState("saving","Verificando perfil en WhatsApp…");api(PANEL_PERSONALITY_PATH+"/whatsapp-profile-sync",{method:"POST",body:"{}"}).then(function(result){nxShowWhatsAppProfileSync(result&&result.whatsapp_profile_sync,true);}).catch(function(error){var sync=error.body&&error.body.whatsapp_profile_sync;if(sync)nxShowWhatsAppProfileSync(sync,true);else{nxSetSaveState("error","WhatsApp no actualizado");nxToast(error.body&&error.body.message||"No pudimos actualizar el perfil de WhatsApp.","error");}}).finally(function(){nxConfigSaving=false;nxSetApplyButton(false);});}
function saveBotConfiguration(explicit){if(!state.personalityCanEdit||nxConfigSaving)return;if(!state.personalityDirty){if(explicit)syncBotWhatsAppProfile();return;}clearTimeout(nxConfigSaveTimer);var sequence=nxConfigSaveSequence,payload=nxClone(state.personality);nxConfigSaving=true;nxSetApplyButton(true);nxSetSaveState("saving","Guardando y verificando…");api(PANEL_PERSONALITY_PATH,{method:"PUT",body:JSON.stringify({personality:payload})}).then(function(result){if(sequence!==nxConfigSaveSequence)return;if(!result||result.applied!==true)throw new Error("apply_not_confirmed");fillBotPersonality(result);var sync=result&&result.whatsapp_profile_sync;if(sync&&sync.status!=="unchanged")nxShowWhatsAppProfileSync(sync,explicit);else{nxSetSaveState("saved","Cambios aplicados al bot");if(explicit)nxToast("Cambios guardados y aplicados al bot.");}}).catch(function(error){if(sequence!==nxConfigSaveSequence)return;nxSetSaveState("error","No se aplicó · reintenta");nxToast(error.body&&error.body.message||"No pudimos guardar y aplicar los cambios.","error");}).finally(function(){nxConfigSaving=false;nxSetApplyButton(false);if(state.personalityDirty&&sequence!==nxConfigSaveSequence){clearTimeout(nxConfigSaveTimer);nxConfigSaveTimer=setTimeout(function(){saveBotConfiguration(false);},100);}});}
function openBotConfigTest(){var modal=document.getElementById("nxTestModal");if(modal){modal.hidden=false;setTimeout(function(){var input=document.getElementById("nxTestInput");if(input)input.focus();},0);}}
function closeBotConfigTest(){var modal=document.getElementById("nxTestModal");if(modal)modal.hidden=true;}
function runBotConfigTest(){var input=document.getElementById("nxTestInput"),message=input&&input.value.trim(),button=document.getElementById("nxTestSend");if(!message)return;if(state.personalityDirty){text("nxTestReply","Primero aplica los cambios pendientes.");saveBotConfiguration(true);return;}text("nxTestUser",message);text("nxTestReply","Pensando…");if(button){button.disabled=true;button.textContent="Probando…";}api(PANEL_PERSONALITY_PATH+"/test",{method:"POST",body:JSON.stringify({message:message})}).then(function(payload){if(!payload||payload.applied!==true)throw new Error("apply_not_confirmed");text("nxTestReply",payload.reply||"No recibimos respuesta.");}).catch(function(error){text("nxTestReply",error.body&&error.body.message||"No pudimos generar la prueba.");}).finally(function(){if(button){button.disabled=false;button.textContent="Probar respuesta";}});}
document.addEventListener("keydown",function(event){if(event.key==="Escape"){var modal=document.getElementById("nxTestModal");if(modal&&!modal.hidden)closeBotConfigTest();}});
